'use strict';const cases=[['set5_028','spell'],['set6_026','spell'],['set6_026','food'],['set6_026','copy']];function setup(c,s,id,variant){s.phase='MAIN_PHASE';s.turnNumber=3;s.activePlayerId='P1';s.pendingEffect=null;for(const p of s.playerOrder)for(const z of ['field','hand','food','discard','territory'])s.player(p)[z]=[];s.player('P1').availableCost=10;function put(id,z,p='P1'){const d=c.getCardDefinition(id),x=new c.CardInstance({instanceId:s.nextInstanceId(),cardId:id,ownerId:p,controllerId:p,zone:z,baseHp:d.baseHp,currentHp:d.baseHp});s.player(p)[z.toLowerCase()].push(x);return x;}put(id,'HAND');if(variant!=='spell'){put('set4_062','HAND');put('minomushi_no_kakuremino','FOOD');put(variant==='copy'?'set4_053':'set2_048','FOOD');}else{put('jinkaichu_no_bakunetsudan','HAND');const enemy=put(id,'FIELD','P2'),att=put('minomushi_no_kakuremino','HAND','P2');s.player('P2').hand.pop();att.zone='FIELD';enemy.attachments.push(att);enemy.currentHp=c.calculateMaxHp(enemy,s);put('kabutomushi','FIELD','P2').currentHp=100;put('okamakiri','FIELD','P2').currentHp=100;}}module.exports={cases,setup};